package com.fatapps.fucker.hook;

/** Original clean AMap quick-tool icons, embedded so AJX promo badges need not be masked. */
final class CleanIconData {
    private CleanIconData() {
    }

    static String forMarker(String marker) {
        if ("订酒店".equals(marker)) {
            return HOTEL;
        }
        if ("超划算".equals(marker)) {
            // Repair the single dropped character in the embedded literal.
            return BARGAIN.replace("Dtvjn3HPP", "Dtvjn3nHPP");
        }
        return null;
    }

    private static final String HOTEL =
            "";

    private static final String BARGAIN =
            "";
}
